    { id=20527, tab=2, tier=2, col=0, name="Holy Nova", icon="spell_holy_holynova", maxRank=1, prereqTalent=0, prereqPoints=10, wired=true, tooltip={ "Causes an explosion of holy light around the caster, causing 29 to 34 Holy damage to all enemy targets within 10 yards and healing all party members within 10 yards for 54 to 63. These effects cause no threat." }, grant={ [1]=15237 }, localized={deDE={name="Heilige Nova", tooltip={ "Löst eine Explosion heiligen Lichts um den Zaubernden aus, die allen feindlichen Zielen im Umkreis von 10 Metern 29 bis 34 Heiligschaden zufügt und alle Gruppenmitglieder im Umkreis von 10 Metern um 54 bis 63 heilt. Diese Effekte erzeugen keine Bedrohung." }}} },
    { id=20528, tab=2, tier=2, col=1, name="Blessed Recovery", icon="spell_holy_blessedrecovery", maxRank=3, prereqTalent=0, prereqPoints=10, wired=true, tooltip={ "After being struck by a melee or ranged critical hit, heal 8% of the damage taken over 6 sec.", "After being struck by a melee or ranged critical hit, heal 16% of the damage taken over 6 sec.", "After being struck by a melee or ranged critical hit, heal 25% of the damage taken over 6 sec." }, localized={deDE={name="Gesegnete Erholung", tooltip={ "Heilt nach einem erlittenen kritischen Nahkampf- oder Fernkampftreffer 8% des erlittenen Schadens im Verlauf von 6 Sek.", "Heilt nach einem erlittenen kritischen Nahkampf- oder Fernkampftreffer 16% des erlittenen Schadens im Verlauf von 6 Sek.", "Heilt nach einem erlittenen kritischen Nahkampf- oder Fernkampftreffer 25% des erlittenen Schadens im Verlauf von 6 Sek." }}} },
    { id=20529, tab=2, tier=2, col=3, name="Inspiration", icon="spell_holy_layonhands", maxRank=3, prereqTalent=0, prereqPoints=10, wired=true, tooltip={ "Increases your target's armor by 8% for 15 sec after getting a critical effect from your Flash Heal, Heal, Greater Heal, Binding Heal, Prayer of Healing, or Circle of Healing spell.", "Increases your target's armor by 16% for 15 sec after getting a critical effect from your Flash Heal, Heal, Greater Heal, Binding Heal, Prayer of Healing, or Circle of Healing spell.", "Increases your target's armor by 25% for 15 sec after getting a critical effect from your Flash Heal, Heal, Greater Heal, Binding Heal, Prayer of Healing, or Circle of Healing spell." }, localized={deDE={name="Inspiration", tooltip={ "Erhöht nach einem kritischen Effekt Eurer Zauber 'Blitzheilung', 'Heilung', 'Große Heilung', 'Verbindende Heilung', 'Gebet der Heilung' oder 'Kreis der Heilung' die Rüstung Eures Ziels 15 Sek. lang um 8%.", "Erhöht nach einem kritischen Effekt Eurer Zauber 'Blitzheilung', 'Heilung', 'Große Heilung', 'Verbindende Heilung', 'Gebet der Heilung' oder 'Kreis der Heilung' die Rüstung Eures Ziels 15 Sek. lang um 16%.", "Erhöht nach einem kritischen Effekt Eurer Zauber 'Blitzheilung', 'Heilung', 'Große Heilung', 'Verbindende Heilung', 'Gebet der Heilung' oder 'Kreis der Heilung' die Rüstung Eures Ziels 15 Sek. lang um 25%." }}} },
    { id=20530, tab=2, tier=3, col=0, name="Holy Reach", icon="spell_holy_purify", maxRank=2, prereqTalent=0, prereqPoints=15, wired=true, tooltip={ "Increases the range of your Smite and Holy Fire spells and the radius of your Prayer of Healing, Holy Nova and Circle of Healing spells by 10%.", "Increases the range of your Smite and Holy Fire spells and the radius of your Prayer of Healing, Holy Nova and Circle of Healing spells by 20%." }, grant={ [1]=27789, [2]=27790 }, localized={deDE={name="Heilige Reichweite", tooltip={ "Erhöht die Reichweite Eurer Zauber 'Göttliche Pein' und 'Heiliges Feuer' sowie den Radius Eurer Zauber 'Gebet der Heilung', 'Heilige Nova' und 'Kreis der Heilung' um 10%.", "Erhöht die Reichweite Eurer Zauber 'Göttliche Pein' und 'Heiliges Feuer' sowie den Radius Eurer Zauber 'Gebet der Heilung', 'Heilige Nova' und 'Kreis der Heilung' um 20%." }}} },
    { id=20531, tab=2, tier=3, col=1, name="Improved Healing", icon="spell_holy_heal02", maxRank=3, prereqTalent=0, prereqPoints=15, wired=true, tooltip={ "Reduces the mana cost of your Lesser Heal, Heal, and Greater Heal spells by 5%.", "Reduces the mana cost of your Lesser Heal, Heal, and Greater Heal spells by 10%.", "Reduces the mana cost of your Lesser Heal, Heal, and Greater Heal spells by 15%." }, grant={ [1]=14912, [2]=15013, [3]=15014 }, localized={deDE={name="Verbesserte Heilung", tooltip={ "Verringert die Manakosten Eurer Zauber 'Geringe Heilung', 'Heilung' und 'Große Heilung' um 5%.", "Verringert die Manakosten Eurer Zauber 'Geringe Heilung', 'Heilung' und 'Große Heilung' um 10%.", "Verringert die Manakosten Eurer Zauber 'Geringe Heilung', 'Heilung' und 'Große Heilung' um 15%." }}} },
    { id=20532, tab=2, tier=3, col=2, name="Searing Light", icon="spell_holy_searinglightpriest", maxRank=2, prereqTalent=20526, prereqPoints=15, wired=true, tooltip={ "Increases the damage of your Smite and Holy Fire spells by 5%.", "Increases the damage of your Smite and Holy Fire spells by 10%." }, localized={deDE={name="Sengendes Licht", tooltip={ "Erhöht den Schaden Eurer Zauber 'Göttliche Pein' und 'Heiliges Feuer' um 5%.", "Erhöht den Schaden Eurer Zauber 'Göttliche Pein' und 'Heiliges Feuer' um 10%." }}} },
    { id=20533, tab=2, tier=4, col=0, name="Healing Prayers", icon="spell_holy_prayerofhealing02", maxRank=2, prereqTalent=0, prereqPoints=20, wired=true, tooltip={ "Reduces the mana cost of your Prayer of Healing and Prayer of Mending spell by 10%.", "Reduces the mana cost of your Prayer of Healing and Prayer of Mending spell by 20%." }, grant={ [1]=14911, [2]=15018 }, localized={deDE={name="Heilgebete", tooltip={ "Verringert die Manakosten Eurer Zauber 'Gebet der Heilung' und 'Gebet der Besserung' um 10%.", "Verringert die Manakosten Eurer Zauber 'Gebet der Heilung' und 'Gebet der Besserung' um 20%." }}} },
    { id=20534, tab=2, tier=4, col=1, name="Spirit of Redemption", icon="inv_enchant_essenceeternallarge", maxRank=1, prereqTalent=0, prereqPoints=20, wired=true, tooltip={ "Increases total Spirit by 5% and upon death, the priest becomes the Spirit of Redemption for 15 sec. The Spirit of Redemption cannot move, attack, be attacked or targeted by any spells or effects. While in this form the priest can cast any healing spell free of cost. When the effect ends, the priest dies." }, grant={ [1]=20711 }, localized={deDE={name="Geist der Erlösung", tooltip={ "Erhöht die gesamte Willenskraft um 5% und verwandelt den Priester bei seinem Tod 15 Sek. lang in den Geist der Erlösung. Der Geist der Erlösung kann sich nicht bewegen oder angreifen und kann weder angegriffen noch von Zaubern oder Effekten anvisiert werden. In dieser Gestalt kann der Priester alle Heilzauber kostenlos wirken. Wenn der Effekt endet, stirbt der Priester." }}} },
    { id=20535, tab=2, tier=4, col=2, name="Spiritual Guidance", icon="spell_holy_spiritualguidence", maxRank=5, prereqTalent=0, prereqPoints=20, wired=true, tooltip={ "Increases spell damage and healing by up to 5% of your total Spirit.", "Increases spell damage and healing by up to 10% of your total Spirit.", "Increases spell damage and healing by up to 15% of your total Spirit.", "Increases spell damage and healing by up to 20% of your total Spirit.", "Increases spell damage and healing by up to 25% of your total Spirit." }, grant={ [1]=14901, [2]=15028, [3]=15029, [4]=15030, [5]=15031 }, localized={deDE={name="Geistige Führung", tooltip={ "Erhöht Zauberschaden und Heilung um bis zu 5% Eurer gesamten Willenskraft.", "Erhöht Zauberschaden und Heilung um bis zu 10% Eurer gesamten Willenskraft.", "Erhöht Zauberschaden und Heilung um bis zu 15% Eurer gesamten Willenskraft.", "Erhöht Zauberschaden und Heilung um bis zu 20% Eurer gesamten Willenskraft.", "Erhöht Zauberschaden und Heilung um bis zu 25% Eurer gesamten Willenskraft." }}} },
    { id=20536, tab=2, tier=5, col=0, name="Surge of Light", icon="spell_holy_surgeoflight", maxRank=2, prereqTalent=0, prereqPoints=25, wired=true, tooltip={ "Your spell criticals have a 25% chance to cause your next Smite spell to be instant cast, cost no mana but be incapable of a critical hit. This effect lasts 10 sec.", "Your spell criticals have a 50% chance to cause your next Smite spell to be instant cast, cost no mana but be incapable of a critical hit. This effect lasts 10 sec." }, localized={deDE={name="Lichtwoge", tooltip={ "Kritische Effekte Eurer Zauber haben eine Chance von 25%, dass Euer nächster Zauber 'Göttliche Pein' sofort gewirkt wird, kein Mana kostet und keinen kritischen Treffer erzielen kann. Dieser Effekt hält 10 Sek. lang an.", "Kritische Effekte Eurer Zauber haben eine Chance von 50%, dass Euer nächster Zauber 'Göttliche Pein' sofort gewirkt wird, kein Mana kostet und keinen kritischen Treffer erzielen kann. Dieser Effekt hält 10 Sek. lang an." }}} },
    { id=20537, tab=2, tier=5, col=2, name="Spiritual Healing", icon="spell_nature_moonglow", maxRank=5, prereqTalent=0, prereqPoints=25, wired=true, tooltip={ "Increases the amount healed by your healing spells by 2%.", "Increases the amount healed by your healing spells by 4%.", "Increases the amount healed by your healing spells by 6%.", "Increases the amount healed by your healing spells by 8%.", "Increases the amount healed by your healing spells by 10%." }, localized={deDE={name="Spirituelle Heilung", tooltip={ "Erhöht die durch Eure Heilzauber geheilte Gesundheit um 2%.", "Erhöht die durch Eure Heilzauber geheilte Gesundheit um 4%.", "Erhöht die durch Eure Heilzauber geheilte Gesundheit um 6%.", "Erhöht die durch Eure Heilzauber geheilte Gesundheit um 8%.", "Erhöht die durch Eure Heilzauber geheilte Gesundheit um 10%." }}} },
    { id=20538, tab=2, tier=6, col=0, name="Holy Concentration", icon="spell_holy_fanaticism", maxRank=3, prereqTalent=0, prereqPoints=30, wired=true, tooltip={ "Gives you a 2% chance to enter a Clearcasting state after casting any Flash Heal, Binding Heal, or Greater Heal spell. The Clearcasting state reduces the mana cost of your next Flash Heal, Binding Heal, or Greater Heal spell by 100%.", "Gives you a 4% chance to enter a Clearcasting state after casting any Flash Heal, Binding Heal, or Greater Heal spell. The Clearcasting state reduces the mana cost of your next Flash Heal, Binding Heal, or Greater Heal spell by 100%.", "Gives you a 6% chance to enter a Clearcasting state after casting any Flash Heal, Binding Heal, or Greater Heal spell. The Clearcasting state reduces the mana cost of your next Flash Heal, Binding Heal, or Greater Heal spell by 100%." }, localized={deDE={name="Heilige Konzentration", tooltip={ "Gewährt Euch nach dem Wirken von 'Blitzheilung', 'Verbindende Heilung' oder 'Große Heilung' eine Chance von 2%, in einen Freizauberzustand zu gelangen. Der Freizauberzustand verringert die Manakosten Eurer nächsten 'Blitzheilung', 'Verbindenden Heilung' oder 'Großen Heilung' um 100%.", "Gewährt Euch nach dem Wirken von 'Blitzheilung', 'Verbindende Heilung' oder 'Große Heilung' eine Chance von 4%, in einen Freizauberzustand zu gelangen. Der Freizauberzustand verringert die Manakosten Eurer nächsten 'Blitzheilung', 'Verbindenden Heilung' oder 'Großen Heilung' um 100%.", "Gewährt Euch nach dem Wirken von 'Blitzheilung', 'Verbindende Heilung' oder 'Große Heilung' eine Chance von 6%, in einen Freizauberzustand zu gelangen. Der Freizauberzustand verringert die Manakosten Eurer nächsten 'Blitzheilung', 'Verbindenden Heilung' oder 'Großen Heilung' um 100%." }}} },
    { id=20539, tab=2, tier=6, col=1, name="Lightwell", icon="spell_holy_summonlightwell", maxRank=1, prereqTalent=20534, prereqPoints=30, wired=true, tooltip={ "Creates a Holy Lightwell. Members of your raid or party can click the Lightwell to restore 801 health over 6 sec. Attacks done to you equal to 30% of your total health will cancel the effect. Lightwell lasts for 3 min or 10 charges." }, grant={ [1]=948051 }, localized={deDE={name="Lichtbrunnen", tooltip={ "Erschafft einen heiligen Lichtbrunnen. Mitglieder Eurer Gruppe oder Eures Schlachtzugs können den Lichtbrunnen anklicken, um im Verlauf von 6 Sek. 801 Gesundheit wiederherzustellen. Erleidet Ihr durch Angriffe Schaden in Höhe von 30% Eurer gesamten Gesundheit, endet der Effekt. Der Lichtbrunnen hält 3 Min. lang oder für 10 Aufladungen an." }}} },
    { id=20540, tab=2, tier=6, col=2, name="Blessed Resilience", icon="spell_holy_blessedresillience", maxRank=3, prereqTalent=0, prereqPoints=30, wired=true, tooltip={ "Critical hits made against you have a 20% chance to prevent you from being critically hit again for 6 sec.", "Critical hits made against you have a 40% chance to prevent you from being critically hit again for 6 sec.", "Critical hits made against you have a 60% chance to prevent you from being critically hit again for 6 sec." }, localized={deDE={name="Gesegnete Abhärtung", tooltip={ "Kritische Treffer gegen Euch haben eine Chance von 20%, weitere kritische Treffer gegen Euch 6 Sek. lang zu verhindern.", "Kritische Treffer gegen Euch haben eine Chance von 40%, weitere kritische Treffer gegen Euch 6 Sek. lang zu verhindern.", "Kritische Treffer gegen Euch haben eine Chance von 60%, weitere kritische Treffer gegen Euch 6 Sek. lang zu verhindern." }}} },
    { id=20541, tab=2, tier=7, col=1, name="Empowered Healing", icon="spell_holy_greaterheal", maxRank=5, prereqTalent=0, prereqPoints=35, wired=true, tooltip={ "Your Greater Heal spell gains an additional 4% and your Flash Heal and Binding Heal gain an additional 2% of your bonus healing effects.", "Your Greater Heal spell gains an additional 8% and your Flash Heal and Binding Heal gain an additional 4% of your bonus healing effects.", "Your Greater Heal spell gains an additional 12% and your Flash Heal and Binding Heal gain an additional 6% of your bonus healing effects.", "Your Greater Heal spell gains an additional 16% and your Flash Heal and Binding Heal gain an additional 8% of your bonus healing effects.", "Your Greater Heal spell gains an additional 20% and your Flash Heal and Binding Heal gain an additional 10% of your bonus healing effects." }, localized={deDE={name="Machtvolle Heilung", tooltip={ "Euer Zauber 'Große Heilung' erhält zusätzlich 4% und Eure Zauber 'Blitzheilung' und 'Verbindende Heilung' zusätzlich 2% Eurer Heilungsboni.", "Euer Zauber 'Große Heilung' erhält zusätzlich 8% und Eure Zauber 'Blitzheilung' und 'Verbindende Heilung' zusätzlich 4% Eurer Heilungsboni.", "Euer Zauber 'Große Heilung' erhält zusätzlich 12% und Eure Zauber 'Blitzheilung' und 'Verbindende Heilung' zusätzlich 6% Eurer Heilungsboni.", "Euer Zauber 'Große Heilung' erhält zusätzlich 16% und Eure Zauber 'Blitzheilung' und 'Verbindende Heilung' zusätzlich 8% Eurer Heilungsboni.", "Euer Zauber 'Große Heilung' erhält zusätzlich 20% und Eure Zauber 'Blitzheilung' und 'Verbindende Heilung' zusätzlich 10% Eurer Heilungsboni." }}} },
    { id=20542, tab=2, tier=8, col=1, name="Circle of Healing", icon="spell_holy_circleofrenewal", maxRank=1, prereqTalent=0, prereqPoints=40, wired=true, tooltip={ "Heals friendly target and that target's party members within 15 yards of the target for 250 to 274." }, grant={ [1]=948046 }, localized={deDE={name="Kreis der Heilung", tooltip={ "Heilt ein befreundetes Ziel und dessen Gruppenmitglieder im Umkreis von 15 Metern um das Ziel um 250 bis 274." }}} },
    { id=20543, tab=3, tier=0, col=1, name="Spirit Tap", icon="spell_shadow_requiem", maxRank=5, prereqTalent=0, prereqPoints=0, wired=true, tooltip={ "Gives you a 20% chance to gain a 100% bonus to your Spirit after killing a target that yields experience or honor. For the duration, your mana will regenerate at a 50% rate while casting. Lasts 15 sec.", "Gives you a 40% chance to gain a 100% bonus to your Spirit after killing a target that yields experience or honor. For the duration, your mana will regenerate at a 50% rate while casting. Lasts 15 sec.", "Gives you a 60% chance to gain a 100% bonus to your Spirit after killing a target that yields experience or honor. For the duration, your mana will regenerate at a 50% rate while casting. Lasts 15 sec.", "Gives you a 80% chance to gain a 100% bonus to your Spirit after killing a target that yields experience or honor. For the duration, your mana will regenerate at a 50% rate while casting. Lasts 15 sec.", "Gives you a 100% chance to gain a 100% bonus to your Spirit after killing a target that yields experience or honor. For the duration, your mana will regenerate at a 50% rate while casting. Lasts 15 sec." }, localized={deDE={name="Willensentzug", tooltip={ "Gewährt Euch nach dem Töten eines Ziels, das Erfahrung oder Ehre gewährt, eine Chance von 20%, einen Bonus von 100% auf Eure Willenskraft zu erhalten. Während der Wirkungsdauer regeneriert Euer Mana beim Zauberwirken mit einer Rate von 50%. Hält 15 Sek. lang an.", "Gewährt Euch nach dem Töten eines Ziels, das Erfahrung oder Ehre gewährt, eine Chance von 40%, einen Bonus von 100% auf Eure Willenskraft zu erhalten. Während der Wirkungsdauer regeneriert Euer Mana beim Zauberwirken mit einer Rate von 50%. Hält 15 Sek. lang an.", "Gewährt Euch nach dem Töten eines Ziels, das Erfahrung oder Ehre gewährt, eine Chance von 60%, einen Bonus von 100% auf Eure Willenskraft zu erhalten. Während der Wirkungsdauer regeneriert Euer Mana beim Zauberwirken mit einer Rate von 50%. Hält 15 Sek. lang an.", "Gewährt Euch nach dem Töten eines Ziels, das Erfahrung oder Ehre gewährt, eine Chance von 80%, einen Bonus von 100% auf Eure Willenskraft zu erhalten. Während der Wirkungsdauer regeneriert Euer Mana beim Zauberwirken mit einer Rate von 50%. Hält 15 Sek. lang an.", "Gewährt Euch nach dem Töten eines Ziels, das Erfahrung oder Ehre gewährt, eine Chance von 100%, einen Bonus von 100% auf Eure Willenskraft zu erhalten. Während der Wirkungsdauer regeneriert Euer Mana beim Zauberwirken mit einer Rate von 50%. Hält 15 Sek. lang an." }}} },
    { id=20544, tab=3, tier=0, col=2, name="Blackout", icon="spell_shadow_gathershadows", maxRank=5, prereqTalent=0, prereqPoints=0, wired=true, tooltip={ "Gives your Shadow damage spells a 2% chance to stun the target for 3 sec.", "Gives your Shadow damage spells a 4% chance to stun the target for 3 sec.", "Gives your Shadow damage spells a 6% chance to stun the target for 3 sec.", "Gives your Shadow damage spells a 8% chance to stun the target for 3 sec.", "Gives your Shadow damage spells a 10% chance to stun the target for 3 sec." }, localized={deDE={name="Blackout", tooltip={ "Gewährt Euren Schattenschadenszaubern eine Chance von 2%, das Ziel 3 Sek. lang zu betäuben.", "Gewährt Euren Schattenschadenszaubern eine Chance von 4%, das Ziel 3 Sek. lang zu betäuben.", "Gewährt Euren Schattenschadenszaubern eine Chance von 6%, das Ziel 3 Sek. lang zu betäuben.", "Gewährt Euren Schattenschadenszaubern eine Chance von 8%, das Ziel 3 Sek. lang zu betäuben.", "Gewährt Euren Schattenschadenszaubern eine Chance von 10%, das Ziel 3 Sek. lang zu betäuben." }}} },
    { id=20545, tab=3, tier=1, col=0, name="Shadow Affinity", icon="spell_shadow_shadowward", maxRank=3, prereqTalent=0, prereqPoints=5, wired=true, tooltip={ "Reduces the threat generated by your Shadow spells by 8%.", "Reduces the threat generated by your Shadow spells by 16%.", "Reduces the threat generated by your Shadow spells by 25%." }, localized={deDE={name="Schattenaffinität", tooltip={ "Verringert die von Euren Schattenzaubern erzeugte Bedrohung um 8%.", "Verringert die von Euren Schattenzaubern erzeugte Bedrohung um 16%.", "Verringert die von Euren Schattenzaubern erzeugte Bedrohung um 25%." }}} },
    { id=20546, tab=3, tier=1, col=1, name="Improved Shadow Word: Pain", icon="spell_shadow_shadowwordpain", maxRank=2, prereqTalent=0, prereqPoints=5, wired=true, tooltip={ "Increases the duration of your Shadow Word: Pain spell by 3 sec.", "Increases the duration of your Shadow Word: Pain spell by 6 sec." }, localized={deDE={name="Verbessertes Schattenwort: Schmerz", tooltip={ "Erhöht die Dauer Eures Zaubers 'Schattenwort: Schmerz' um 3 Sek.", "Erhöht die Dauer Eures Zaubers 'Schattenwort: Schmerz' um 6 Sek." }}} },
    { id=20547, tab=3, tier=1, col=2, name="Shadow Focus", icon="spell_shadow_burningspirit", maxRank=5, prereqTalent=0, prereqPoints=5, wired=true, tooltip={ "Reduces your target's chance to resist your Shadow spells by 2%.", "Reduces your target's chance to resist your Shadow spells by 4%.", "Reduces your target's chance to resist your Shadow spells by 6%.", "Reduces your target's chance to resist your Shadow spells by 8%.", "Reduces your target's chance to resist your Shadow spells by 10%." }, localized={deDE={name="Schattenfokus", tooltip={ "Verringert die Chance, dass Euer Ziel Euren Schattenzaubern widersteht, um 2%.", "Verringert die Chance, dass Euer Ziel Euren Schattenzaubern widersteht, um 4%.", "Verringert die Chance, dass Euer Ziel Euren Schattenzaubern widersteht, um 6%.", "Verringert die Chance, dass Euer Ziel Euren Schattenzaubern widersteht, um 8%.", "Verringert die Chance, dass Euer Ziel Euren Schattenzaubern widersteht, um 10%." }}} },
